<?php
namespace App\Http\Controllers;
use App\Models\LanguageCourse; use App\Support\{CenterCode,ExcelExporter}; use Illuminate\Http\{Request,RedirectResponse}; use Illuminate\View\View;
class LanguageCourseController extends Controller { public function index(Request $r):View{$q=LanguageCourse::latest();if($r->filled('q')){$s=$r->string('q');$q->where(fn($b)=>$b->where('name','like',"%$s%")->orWhere('textbook','like',"%$s%"));}return view('language.center-courses.index',['items'=>$q->paginate(20)->withQueryString()]);}public function create():View{return view('language.center-courses.form',['item'=>new LanguageCourse]);}public function store(Request $r):RedirectResponse{$d=$this->data($r);$d['code']=CenterCode::next('language_courses','KH');LanguageCourse::create($d);return redirect()->route('language-center-courses.index')->with('success','Đã thêm khóa học.');}public function edit(LanguageCourse $languageCenterCourse):View{return view('language.center-courses.form',['item'=>$languageCenterCourse]);}public function update(Request $r,LanguageCourse $languageCenterCourse):RedirectResponse{$languageCenterCourse->update($this->data($r));return redirect()->route('language-center-courses.index')->with('success','Đã cập nhật khóa học.');}public function destroy(LanguageCourse $languageCenterCourse):RedirectResponse{$languageCenterCourse->delete();return back()->with('success','Đã xóa khóa học.');}public function export(){return ExcelExporter::download('khoa-hoc-trung-tam-'.date('Ymd').'.xlsx',['Mã','Tên khóa','Giáo trình','Học phí','Thời lượng giờ','Số buổi','Trạng thái'],LanguageCourse::withTrashed()->get()->map(fn($i)=>[$i->code,$i->name,$i->textbook,$i->tuition,$i->duration_hours,$i->sessions,$i->active?'Hoạt động':'Ngừng']));}private function data(Request $r):array{$d=$r->validate(['name'=>'required|max:255','textbook'=>'nullable|max:255','tuition'=>'required|numeric|min:0','duration_hours'=>'required|numeric|min:0','sessions'=>'required|integer|min:0','description'=>'nullable']);$d['active']=$r->boolean('active');return $d;} }
